  1	// Package gitops shells out to the git binary so the user's existing
  2	// git configuration and credentials apply unchanged.
  3	package gitops
  4	
  5	import (
  6		"fmt"
  7		"os"
  8		"os/exec"
  9		"path/filepath"
 10		"regexp"
 11		"strings"
 12	
 13		"github.com/neutrospec/canopy/internal/safefile"
 14	)
 15	
 16	type Status struct {
 17		IsRepo  bool     `json:"is_repo"`
 18		Branch  string   `json:"branch"`
 19		Dirty   int      `json:"dirty"`  // modified + untracked paths
 20		Ahead   int      `json:"ahead"`  // commits not pushed
 21		Behind  int      `json:"behind"` // commits not pulled
 22		Changed []string `json:"changed,omitempty"`
 23	}
 24	
 25	func run(dir string, args ...string) (string, error) {
 26		cmd := exec.Command("git", args...)
 27		cmd.Dir = dir
 28		out, err := cmd.CombinedOutput()
 29		if err != nil {
 30			return "", fmt.Errorf("git %s: %w: %s", strings.Join(args, " "), err, strings.TrimSpace(string(out)))
 31		}
 32		return string(out), nil
 33	}
 34	
 35	var branchRe = regexp.MustCompile(`^## (\S+?)(?:\.\.\.(\S+))?(?: \[(.*)\])?$`)
 36	
 37	// GetStatus inspects the wiki repo. A non-repo directory returns
 38	// Status{IsRepo: false} without error.
 39	func GetStatus(dir string) (*Status, error) {
 40		out, err := run(dir, "status", "--porcelain=v1", "-b")
 41		if err != nil {
 42			if strings.Contains(err.Error(), "not a git repository") {
 43				return &Status{}, nil
 44			}
 45			return nil, err
 46		}
 47		st := &Status{IsRepo: true}
 48		for i, line := range strings.Split(strings.TrimRight(out, "\n"), "\n") {
 49			if i == 0 && strings.HasPrefix(line, "## ") {
 50				if m := branchRe.FindStringSubmatch(line); m != nil {
 51					st.Branch = m[1]
 52					for _, part := range strings.Split(m[3], ", ") {
 53						if n, ok := strings.CutPrefix(part, "ahead "); ok {
 54							fmt.Sscanf(n, "%d", &st.Ahead)
 55						}
 56						if n, ok := strings.CutPrefix(part, "behind "); ok {
 57							fmt.Sscanf(n, "%d", &st.Behind)
 58						}
 59					}
 60				}
 61				continue
 62			}
 63			if line == "" {
 64				continue
 65			}
 66			if len(line) > 3 && strings.HasPrefix(filepath.Base(strings.Trim(line[3:], "\"")), safefile.TempPrefix) {
 67				continue
 68			}
 69			st.Dirty++
 70			if len(line) > 3 {
 71				st.Changed = append(st.Changed, strings.TrimSpace(line[3:]))
 72			}
 73		}
 74		return st, nil
 75	}
