 77	// Pull rebases local work onto origin. Called before committing so a
 78	// user's direct edits (e.g. via Obsidian on another machine) merge in.
 79	func Pull(dir string) (string, error) {
 80		if err := RequireSafe(dir); err != nil {
 81			return "", err
 82		}
 83		out, err := run(dir, "pull", "--rebase", "--autostash")
 84		if err != nil && strings.Contains(err.Error(), "no tracking information") {
 85			return "no upstream configured, skipping pull", nil
 86		}
 87		if err == nil {
 88			err = RequireSafe(dir)
 89		}
 90		return strings.TrimSpace(out), err
 91	}
 92	
 93	func CommitAll(dir, message string) (string, error) {
 94		if err := RequireSafe(dir); err != nil {
 95			return "", err
 96		}
 97		if _, err := run(dir, "add", "-A", "--", ".", ":(glob,exclude)**/"+safefile.TempPrefix+"*"); err != nil {
 98			return "", err
 99		}
100		if err := RequireSafe(dir); err != nil {
101			return "", err
102		}
103		out, err := run(dir, "commit", "-m", message)
104		return strings.TrimSpace(out), err
105	}
106	
107	func Push(dir string) (string, error) {
108		if err := RequireSafe(dir); err != nil {
109			return "", err
110		}
111		out, err := run(dir, "push")
112		if err != nil && strings.Contains(err.Error(), "No configured push destination") {
113			return "no remote configured, skipping push", nil
114		}
115		return strings.TrimSpace(out), err
116	}
117	
118	// RequireSafe refuses unresolved index entries and operations that need a
119	// human decision. In particular, autostash conflicts may leave exit 0 from pull;
120	// the index, not Git's stdout, is the authority. This check precedes add -A.
121	func RequireSafe(dir string) error {
122		unmerged, err := run(dir, "ls-files", "-u")
123		if err != nil {
124			return err
125		}
126		if strings.TrimSpace(unmerged) != "" {
127			return fmt.Errorf("unresolved Git index entries in %s; resolve them manually; local files and autostash are preserved", dir)
128		}
129		for _, name := range []string{"MERGE_HEAD", "CHERRY_PICK_HEAD", "REVERT_HEAD", "rebase-merge", "rebase-apply", "sequencer"} {
130			p, err := run(dir, "rev-parse", "--git-path", name)
131			if err != nil {
132				return err
133			}
134			path := strings.TrimSpace(p)
135			if !filepath.IsAbs(path) {
136				path = filepath.Join(dir, path)
137			}
138			if _, err := os.Lstat(path); err == nil {
139				return fmt.Errorf("Git operation in progress (%s) in %s; finish or abort it manually before sync", name, dir)
140			} else if !os.IsNotExist(err) {
141				return err
142			}
143		}
144		return nil
145	}
146	
147	func Head(dir string) (string, error) {
148		out, err := run(dir, "rev-parse", "--verify", "HEAD")
149		return strings.TrimSpace(out), err
150	}
151	
152	// RemoteTip observes the tracked destination after an ambiguous push failure.
153	// A failed observation remains unknown; subprocess failure alone cannot prove
154	// that a remote rejected a commit (the acknowledgement may have been lost).
155	func RemoteTip(dir string) (string, error) {
156		branch, err := run(dir, "symbolic-ref", "--short", "HEAD")
157		if err != nil {
158			return "", err
159		}
160		branch = strings.TrimSpace(branch)
161		remote, err := run(dir, "config", "--get", "branch."+branch+".remote")
162		if err != nil {
163			return "", err
164		}
165		ref, err := run(dir, "config", "--get", "branch."+branch+".merge")
166		if err != nil {
167			return "", err
168		}
169		out, err := run(dir, "ls-remote", "--exit-code", strings.TrimSpace(remote), strings.TrimSpace(ref))
170		if err != nil {
171			return "", err
172		}
173		fields := strings.Fields(out)
174		if len(fields) < 2 {
175			return "", fmt.Errorf("remote destination cannot be observed")
176		}
177		return fields[0], nil
178	}
