180	// Banner renders the unsynced-state warning shown at the start of every
181	// command. Empty string means the wiki is clean and pushed.
182	func (s *Status) Banner() string {
183		if !s.IsRepo || (s.Dirty == 0 && s.Ahead == 0 && s.Behind == 0) {
184			return ""
185		}
186		var parts []string
187		if s.Dirty > 0 {
188			parts = append(parts, fmt.Sprintf("%d uncommitted change(s)", s.Dirty))
189		}
190		if s.Ahead > 0 {
191			parts = append(parts, fmt.Sprintf("%d unpushed commit(s)", s.Ahead))
192		}
193		if s.Behind > 0 {
194			parts = append(parts, fmt.Sprintf("%d commit(s) behind origin", s.Behind))
195		}
196		return "⚠ wiki has " + strings.Join(parts, ", ") + " — run `canopy sync`"
197	}

