163					if err != nil {
164						return err
165					}
166					r.Stage = "reindex"
167					if err := writeops.Refresh(w, scan); err != nil {
168						return err
169					}
170				}
171				r.Stage = "cleanup"
172				if err := checkout.Complete(w, args[0], res); err != nil {
173					return err
174				}
175				r.Result["cleanup_pending"] = false
