  3	import (
  4		"fmt"
  5		"math/rand"
  6		"sort"
  7		"strings"
  8		"time"
  9	
 10		"github.com/neutrospec/canopy/internal/reads"
 11		"github.com/neutrospec/canopy/internal/store"
 12		"github.com/neutrospec/canopy/internal/wiki"
 13	)
 14	
 15	// Thresholds from the user's 2026-06 Distill & Express design.
 16	const (
 17		forgottenAfter = 30 * 24 * time.Hour // strategy 1: untouched this long
 18		staleHubAfter  = 60 * 24 * time.Hour // strategy 2: hubs untouched this long
 19		minHubLinks    = 4                   // strategy 2: inbound links to count as a hub
 20	)
 21	
 22	// Pick is one resurface candidate with the evidence the agent needs to
 23	// phrase a message without re-reading the whole wiki.
 24	type Pick struct {
 25		Slug        string   `json:"slug"`
 26		RelPath     string   `json:"rel_path"`
 27		Title       string   `json:"title"`
 28		Strategy    string   `json:"strategy"` // random-forgotten | stale-hub
 29		DaysStale   int      `json:"days_stale"`
 30		Backlinks   []string `json:"backlinks,omitempty"`
 31		Outbound    []string `json:"outbound,omitempty"`
 32		Excerpt     string   `json:"excerpt"`
 33		Explanation string   `json:"explanation"`
 34	}
 35	
 36	// PickPages selects up to n resurface candidates.
 37	// strategy: "random" (forgotten), "hub" (stale-but-important), or
 38	// "auto" (70% random / 30% hub, per the original design).
 39	//
 40	// "Forgotten" means no edit AND no access through any door: rd carries
 41	// the web + agent attention aggregates, so a page read yesterday on the
 42	// web or cited by recall is not a candidate (invariant H6). rd may be
 43	// nil (tests, degraded paths) — then edit dates alone decide, as before.
 44	func PickPages(scan *wiki.ScanResult, st *State, rd *reads.State, strategy string, n int, now time.Time, rng *rand.Rand) ([]Pick, error) {
 45		backlinks := scan.Backlinks()
 46	
 47		type cand struct {
 48			page  *wiki.Page
 49			stale time.Duration
 50		}
 51		var forgotten, hubs []cand
 52		for _, p := range scan.Pages {
 53			if !st.eligible(normalizeSlug(p.Slug), now) {
 54				continue
 55			}
 56			touched, err := time.Parse("2006-01-02", firstNonEmpty(p.Updated, p.Created))
 57			if err != nil {
 58				continue // unparseable dates never enter the pool
 59			}
 60			if rd != nil {
 61				if t, ok := rd.LastAccess(p.Slug); ok && t.After(touched) {
 62					touched = t
 63				}
 64			}
 65			stale := now.Sub(touched)
 66			if stale >= forgottenAfter {
 67				forgotten = append(forgotten, cand{p, stale})
 68			}
 69			if stale >= staleHubAfter && len(backlinks[normalizeSlug(p.Slug)]) >= minHubLinks {
 70				hubs = append(hubs, cand{p, stale})
 71			}
 72		}
 73		// Hubs: most-referenced first, older breaks ties.
 74		sort.Slice(hubs, func(i, j int) bool {
 75			bi, bj := len(backlinks[normalizeSlug(hubs[i].page.Slug)]), len(backlinks[normalizeSlug(hubs[j].page.Slug)])
 76			if bi != bj {
 77				return bi > bj
 78			}
 79			return hubs[i].stale > hubs[j].stale
 80		})
 81	
 82		picks := []Pick{}
 83		used := map[string]bool{}
 84		take := func(c cand, strat string) {
 85			if used[c.page.Slug] {
 86				return
 87			}
 88			used[c.page.Slug] = true
 89			days := int(c.stale.Hours() / 24)
 90			p := Pick{
 91				Slug:      c.page.Slug,
 92				RelPath:   c.page.RelPath,
 93				Title:     c.page.Title,
 94				Strategy:  strat,
 95				DaysStale: days,
 96				Backlinks: backlinks[normalizeSlug(c.page.Slug)],
 97				Outbound:  c.page.Links,
 98				Excerpt:   excerpt(c.page.Body),
 99			}
100			// Truthful now that reads feed the pool: "days" really means no
101			// edit and no recorded access (web/agent) for that long.
102			if strat == "stale-hub" {
103				p.Explanation = fmt.Sprintf("%d개 페이지가 여전히 참조하는데 %d일째 열람·갱신이 없음", len(p.Backlinks), days)
104			} else {
105				p.Explanation = fmt.Sprintf("%d일간 열람·갱신이 없던 페이지", days)
106			}
107			picks = append(picks, p)
108		}
109		takeRandomForgotten := func() bool {
110			// Age-weighted random: older pages surface more often.
111			var pool []cand
112			var weights []float64
113			for _, c := range forgotten {
114				if used[c.page.Slug] {
115					continue
116				}
117				pool = append(pool, c)
118				weights = append(weights, c.stale.Hours()/24)
119			}
120			if len(pool) == 0 {
121				return false
122			}
123			var total float64
124			for _, w := range weights {
125				total += w
126			}
127			r := rng.Float64() * total
128			for i, w := range weights {
129				if r -= w; r <= 0 {
130					take(pool[i], "random-forgotten")
131					return true
132				}
133			}
134			take(pool[len(pool)-1], "random-forgotten")
135			return true
136		}
137		takeHub := func() bool {
138			for _, c := range hubs {
139				if !used[c.page.Slug] {
140					take(c, "stale-hub")
141					return true
142				}
143			}
144			return false
145		}
146	
147		for len(picks) < n {
148			var ok bool
149			switch strategy {
150			case "random":
151				ok = takeRandomForgotten()
152			case "hub":
153				ok = takeHub()
154			case "auto":
155				if rng.Float64() < 0.7 {
156					ok = takeRandomForgotten() || takeHub()
157				} else {
158					ok = takeHub() || takeRandomForgotten()
159				}
160			default:
161				return nil, fmt.Errorf("unknown strategy %q (random|hub|auto)", strategy)
162			}
163			if !ok {
164				break
165			}
166		}
167		return picks, nil
168	}
