170	// Bridge is a similar page pair. In default mode only unlinked pairs
171	// are returned (connection candidates). With includeLinked, linked
172	// pairs at high similarity also surface — those are merge/contradiction
173	// candidates for the agent's semantic lint pass.
174	type Bridge struct {
175		A          BridgeSide `json:"a"`
176		B          BridgeSide `json:"b"`
177		Similarity float64    `json:"similarity"`
178		Linked     bool       `json:"linked"`
179	}
180	
181	type BridgeSide struct {
182		Slug    string `json:"slug"`
183		RelPath string `json:"rel_path"`
184		Title   string `json:"title"`
185		Excerpt string `json:"excerpt"`
186	}
187	
188	// PickBridges finds page pairs with cosine similarity >= minSim.
189	// Linked pairs are excluded unless includeLinked is set.
190	func PickBridges(scan *wiki.ScanResult, vectors map[string][]float32, st *State, minSim float64, n int, includeLinked bool, now time.Time) []Bridge {
191		linked := map[string]bool{}
192		for _, p := range scan.Pages {
193			from := normalizeSlug(p.Slug)
194			for _, t := range p.Links {
195				linked[pairKey(from, t)] = true
196			}
197		}
198		var slugs []string
199		for _, p := range scan.Pages {
200			if _, ok := vectors[p.Slug]; ok {
201				slugs = append(slugs, p.Slug)
202			}
203		}
204		sort.Strings(slugs)
205	
206		bridges := []Bridge{}
207		for i := 0; i < len(slugs); i++ {
208			for j := i + 1; j < len(slugs); j++ {
209				a, b := slugs[i], slugs[j]
210				na, nb := normalizeSlug(a), normalizeSlug(b)
211				isLinked := linked[pairKey(na, nb)]
212				if (isLinked && !includeLinked) || !st.pairEligible(na, nb, now) {
213					continue
214				}
215				sim := store.Cosine(vectors[a], vectors[b])
216				if sim < minSim {
217					continue
218				}
219				pa, pb := scan.BySlug[na], scan.BySlug[nb]
220				bridges = append(bridges, Bridge{
221					A:          BridgeSide{Slug: pa.Slug, RelPath: pa.RelPath, Title: pa.Title, Excerpt: excerpt(pa.Body)},
222					B:          BridgeSide{Slug: pb.Slug, RelPath: pb.RelPath, Title: pb.Title, Excerpt: excerpt(pb.Body)},
223					Similarity: sim,
224					Linked:     isLinked,
225				})
226			}
227		}
228		sort.Slice(bridges, func(i, j int) bool { return bridges[i].Similarity > bridges[j].Similarity })
229		if len(bridges) > n {
230			bridges = bridges[:n]
231		}
232		return bridges
233	}
