235	// excerpt returns the first substantive paragraph (skips headings and
236	// link-list lines), capped at 200 runes.
237	func excerpt(body string) string {
238		for _, para := range strings.Split(body, "\n\n") {
239			p := strings.TrimSpace(para)
240			if p == "" || strings.HasPrefix(p, "#") || strings.HasPrefix(p, "- [[") || strings.HasPrefix(p, "|") || strings.HasPrefix(p, ">") || strings.HasPrefix(p, "---") {
241				continue
242			}
243			runes := []rune(strings.ReplaceAll(p, "\n", " "))
244			if len(runes) > 200 {
245				runes = append(runes[:200], '…')
246			}
247			return string(runes)
248		}
249		return ""
250	}
251	
252	func firstNonEmpty(a, b string) string {
253		if a != "" {
254			return a
255		}
256		return b
257	}

