168			RunE: func(cmd *cobra.Command, args []string) error {
169				if n < 1 || n > store.MaxK {
170					return fmt.Errorf("count must be between 1 and %d", store.MaxK)
171				}
172				if math.IsNaN(minSim) || math.IsInf(minSim, 0) || minSim < -1 || minSim > 1 {
173					return fmt.Errorf("min-sim must be finite and between -1 and 1")
174				}
