176				if err != nil {
177					return err
178				}
179				banner(w)
180				st, err := resurface.LoadState(w)
181				if err != nil {
182					return err
183				}
184				if dismiss != "" {
185					a, b, ok := strings.Cut(dismiss, ":")
186					if !ok {
187						return fmt.Errorf("--dismiss wants slug-a:slug-b")
188					}
189					scan, err := wiki.Scan(w)
190					if err != nil {
191						return err
192					}
193					pa, err := scan.Find(a)
194					if err != nil {
195						return err
196					}
197					pb, err := scan.Find(b)
198					if err != nil {
199						return err
200					}
201					st.DismissPair(strings.ToLower(pa.Slug), strings.ToLower(pb.Slug))
202					if err := st.Save(w); err != nil {
203						return err
204					}
205					if !flagJSON {
206						fmt.Println("✓ pair dismissed permanently")
207					}
208					return nil
209				}
210				scan, err := wiki.Scan(w)
211				if err != nil {
212					return err
213				}
214				db, err := store.Open(w.DBPath())
215				if err != nil {
216					return err
217				}
218				defer db.Close()
219				coverage, err := indexer.EnsureCurrentContext(cmd.Context(), w, db, scan, nil, nil)
220				if err != nil {
221					return err
222				}
223				if coverage.NeedsReindex > 0 {
224					fmt.Fprintf(os.Stderr, "warning: %d pages need embeddings; bridge uses only current indexed evidence\n", coverage.NeedsReindex)
225				}
226				vectors, err := db.PageVectors()
227				if err != nil {
228					return err
229				}
230				if len(vectors) == 0 {
231					return fmt.Errorf("no embeddings in the index — run `canopy reindex` first")
232				}
233				now := time.Now()
234				bridges := resurface.PickBridges(scan, vectors, st, minSim, n, includeLinked, now)
235				if !peek && len(bridges) > 0 {
236					for _, b := range bridges {
237						st.MarkPairShown(strings.ToLower(b.A.Slug), strings.ToLower(b.B.Slug), now)
238					}
239					if err := st.Save(w); err != nil {
240						return err
241					}
242				}
243				if flagJSON {
244					return emitJSON(map[string]any{"bridges": bridges, "state_updated": !peek && len(bridges) > 0, "covered_pages": coverage.EmbeddedPages, "needs_reindex": coverage.NeedsReindex, "profile": coverage.Profile})
245				}
246				if len(bridges) == 0 {
247					fmt.Println("no unlinked similar pairs above the threshold — the graph is well connected")
248					return nil
249				}
250				for _, b := range bridges {
251					mark := ""
252					if b.Linked {
253						mark = " (already linked — merge/contradiction candidate)"
254					}
255					fmt.Printf("[%.3f] %s ↔ %s%s\n", b.Similarity, b.A.Slug, b.B.Slug, mark)
256					fmt.Printf("  A: %s\n  B: %s\n", b.A.Title, b.B.Title)
