266		c.Flags().BoolVar(&peek, "peek", false, "don't record pairs in state (preview only)")
267		c.Flags().BoolVar(&includeLinked, "include-linked", false, "also return linked pairs (semantic-lint candidates; raise --min-sim to ~0.85)")
268		c.Flags().StringVar(&dismiss, "dismiss", "", "permanently dismiss a pair: slug-a:slug-b")
