19	func cmdServe() *cobra.Command {
20		var addr string
21		var allowHosts []string
22		c := &cobra.Command{
23			Use:   "serve",
24			Short: "Serve the wiki as a website (search, browsing, and edit proposals)",
25			Long: `Serve renders the wiki over HTTP for humans: page views with
26	backlinks, hybrid search, faceted browsing, and Wikipedia-style
27	missing-page fallback. The body editor files proposals for an agent to
28	review and apply through the CLI; it never writes wiki pages directly.`,
29			RunE: func(cmd *cobra.Command, args []string) error {
30				w, err := loadWiki()
31				if err != nil {
32					return err
33				}
34				banner(w)
35				// Engine failures degrade to keyword search, same as cmdSearch.
36				var eng embed.Engine
37				if embed.Available() && embed.ModelAvailable() {
38					if eng, err = newEngine(); err != nil {
39						fmt.Fprintf(os.Stderr, "search degrades to keyword only (%v)\n", err)
40						eng = nil
41					} else {
42						defer eng.Close()
43					}
44				} else {
45					fmt.Fprintln(os.Stderr, "embedding stack missing — search degrades to keyword only")
46				}
47				srv, err := webui.NewServer(w, eng)
48				if err != nil {
49					return err
50				}
51				// Non-loopback binds require the auth wall (plan-2 D1/D2):
52				// a public address can never serve the wiki unauthenticated.
53				if !webui.IsLoopbackAddr(addr) {
54					code, err := srv.EnableAuth()
55					if err != nil {
56						return err
57					}
58					fmt.Fprintf(os.Stderr, "⚠ %s is reachable beyond localhost — authentication required\n", addr)
59					if code != "" {
60						fmt.Fprintf(os.Stderr, "\n  최초 1회 계정 설정: 브라우저에서 /setup 을 열고 아래 설정 코드를 입력하세요\n")
61						fmt.Fprintf(os.Stderr, "  ┌──────────────────────────┐\n")
62						fmt.Fprintf(os.Stderr, "  │  setup code: %s    │\n", code)
63						fmt.Fprintf(os.Stderr, "  └──────────────────────────┘\n")
64						fmt.Fprintln(os.Stderr, "  (이 코드는 이 터미널에만 표시되며 1회만 사용됩니다)")
65					}
66					fmt.Fprintln(os.Stderr, "  note: 전송 암호화(TLS)는 tailscale 또는 리버스 프록시 사용을 권장합니다")
67				}
68				listener, err := net.Listen("tcp", addr)
69				if err != nil {
70					return err
71				}
72				defer listener.Close()
73				if err := srv.ConfigureListener(listener.Addr().String(), allowHosts); err != nil {
74					return err
75				}
76				hs := &http.Server{Addr: addr, Handler: srv.Handler(), ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 15 * time.Second, IdleTimeout: 60 * time.Second, MaxHeaderBytes: 32 << 10}
77				ctx, stop := signal.NotifyContext(cmd.Context(), os.Interrupt)
78				defer stop()
79				go func() {
80					<-ctx.Done()
81					sctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
82					defer cancel()
83					_ = hs.Shutdown(sctx)
84				}()
85				fmt.Printf("✓ serving %s on http://%s\n", w.Root, addr)
86				if err := hs.Serve(listener); !errors.Is(err, http.ErrServerClosed) {
87					return err
88				}
89				return nil
90			},
91		}
92		c.Flags().StringVar(&addr, "addr", "localhost:8737", "listen address (non-loopback binds require authentication)")
93		c.Flags().StringSliceVar(&allowHosts, "allow-host", nil, "additional trusted Host authorities for a domain/proxy, e.g. wiki.example:443; forwarded headers are ignored")
94		return c
95	}

