  7		"net/http"
  8		"strconv"
  9		"strings"
 10	)
 11	
 12	type hostPolicy struct {
 13		port           string
 14		explicit       map[string]bool
 15		allowLiteralIP bool
 16	}
 17	
 18	func authority(raw string) (host, port string, err error) {
 19		if raw == "" || strings.ContainsAny(raw, "/\\@#? \t\r\n") {
 20			return "", "", fmt.Errorf("invalid Host")
 21		}
 22		host, port, err = net.SplitHostPort(raw)
 23		if err != nil {
 24			host = strings.Trim(raw, "[]")
 25			port = ""
 26			if strings.Contains(host, ":") && net.ParseIP(host) == nil {
 27				return "", "", fmt.Errorf("invalid Host")
 28			}
 29		}
 30		host = strings.ToLower(strings.TrimSuffix(host, "."))
 31		if host == "" {
 32			return "", "", fmt.Errorf("empty Host")
 33		}
 34		if port != "" {
 35			if n, e := strconv.Atoi(port); e != nil || n < 1 || n > 65535 {
 36				return "", "", fmt.Errorf("invalid Host port")
 37			}
 38		}
 39		return host, port, nil
 40	}
 41	
 42	func hostKey(host, port string) string { return host + "\x00" + port }
 43	
 44	// ConfigureListener binds accepted authorities to the real listener. Extra
 45	// authorities are explicit proxy/domain choices; forwarded headers are ignored.
 46	// Configure once before serving requests. NewServer alone accepts loopback only.
 47	func (s *Server) ConfigureListener(addr string, extra []string) error {
 48		host, port, err := net.SplitHostPort(addr)
 49		if err != nil {
 50			return err
 51		}
 52		policy := &hostPolicy{port: port, explicit: map[string]bool{}}
 53		ip := net.ParseIP(host)
 54		policy.allowLiteralIP = host == "" || (ip != nil && ip.IsUnspecified())
 55		if host != "" && !policy.allowLiteralIP {
 56			policy.explicit[hostKey(strings.ToLower(host), port)] = true
 57		}
 58		for _, raw := range extra {
 59			h, p, err := authority(raw)
 60			if err != nil {
 61				return fmt.Errorf("allow-host %q: %w", raw, err)
 62			}
 63			policy.explicit[hostKey(h, p)] = true
 64		}
 65		s.hosts = policy
 66		return nil
 67	}
 68	
 69	func (s *Server) hostGuard(next http.Handler) http.Handler {
 70		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
 71			h, p, err := authority(r.Host)
 72			if err != nil {
 73				http.Error(w, "Host rejected", http.StatusForbidden)
 74				return
 75			}
 76			policy := s.hosts
 77			allowed := false
 78			if policy != nil && policy.explicit[hostKey(h, p)] {
 79				allowed = true
 80			}
 81			portOK := policy == nil || policy.port == "" || p == policy.port
 82			ip := net.ParseIP(h)
 83			if portOK && (h == "localhost" || (ip != nil && ip.IsLoopback())) {
 84				allowed = true
 85			}
 86			if policy != nil && policy.allowLiteralIP && portOK && ip != nil {
 87				allowed = true
 88			}
 89			if !allowed {
 90				http.Error(w, "Host rejected; configure --allow-host for a trusted domain or proxy", http.StatusForbidden)
 91				return
 92			}
 93			w.Header().Set("X-Content-Type-Options", "nosniff")
 94			w.Header().Set("Referrer-Policy", "same-origin")
 95			next.ServeHTTP(w, r)
 96		})
 97	}
 98	
 99	func bodyLimit(path string) int64 {
100		switch {
101		case strings.HasPrefix(path, "/edit/"):
102			return 1 << 20
103		case strings.HasPrefix(path, "/task/"):
104			return 64 << 10
105		case path == "/login" || path == "/setup":
106			return 8 << 10
107		default:
108			return 16 << 10
109		}
110	}
111	
112	func (s *Server) requestLimits(next http.Handler) http.Handler {
113		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
114			if r.Method != http.MethodGet && r.Method != http.MethodHead {
115				r.Body = http.MaxBytesReader(w, r.Body, bodyLimit(r.URL.Path))
116				var err error
117				if strings.HasPrefix(r.Header.Get("Content-Type"), "multipart/form-data") {
118					err = r.ParseMultipartForm(64 << 10)
119					if r.MultipartForm != nil {
120						defer r.MultipartForm.RemoveAll()
121					}
122				} else {
123					err = r.ParseForm()
124				}
125				if err != nil {
126					var max *http.MaxBytesError
127					status := http.StatusBadRequest
128					if errors.As(err, &max) {
129						status = http.StatusRequestEntityTooLarge
130					}
131					http.Error(w, "invalid or oversized form", status)
132					return
133				}
134			}
135			if r.URL.Path == "/search" || r.URL.Path == "/api/search" {
136				select {
137				case s.searchSlots <- struct{}{}:
138					defer func() { <-s.searchSlots }()
139				default:
140					w.Header().Set("Retry-After", "1")
141					http.Error(w, "search queue busy", http.StatusServiceUnavailable)
142					return
143				}
144			}
145			next.ServeHTTP(w, r)
146		})
147	}

